fn generate(n:usize,open:usize,close:usize,path:*[12]u8,out:[*c]u8,index:*usize)void{if(open+close==2*n){for(0..2*n)|i|out[2+index.**(2*n)+i]=path[i];index.*+=1;return;}if(open<n){path[open+close]='(';generate(n,open+1,close,path,out,index);}if(close<open){path[open+close]=')';generate(n,open,close+1,path,out,index);}}
export fn parentheses_generator(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{if(v==null or n!=1 or v[0]<0 or v[0]>6)return -1;const counts=[_]usize{1,1,2,5,14,42,132};const k:usize=@intCast(v[0]);const need=2+counts[k]*2*k;if(need>cap or out==null)return -2;out[0]=@intCast(counts[k]);out[1]=@intCast(counts[k]>>8);var path=[_]u8{0}**12;var index:usize=0;generate(k,0,0,&path,out,&index);return @intCast(need);}
